\usepackage{tikz}
\usepackage{amsmath}
\usetikzlibrary{arrows.meta,shapes.geometric}
% mathsmap-diagram-colours {"version":1,"kind":"geometry","base":[],"semantic":[],"reference":"source page 9, p9-q14-solution-diagram; short-answer position-labelled variant"}
% Planar directed arithmetic network: one shared input, six independent
% two-operation paths, six terminal expressions. Rows follow clockwise
% source positions: top left, top right, right, bottom right, bottom left, left.
% Supplied source operations remain associated with their original paths:
% top left div 2; top right div 5; right times 3; bottom right div 10;
% bottom left minus 30; left plus 10.
\begin{tikzpicture}[
  x=1mm,y=1mm,
  draw=black,line width=0.8pt,
  every node/.style={text=black,font=\fontsize{10}{12}\selectfont,inner sep=0pt},
  op/.style={circle,draw=black,minimum size=12mm,inner sep=0pt},
  result/.style={ellipse,draw=black,minimum width=20mm,minimum height=10mm,inner sep=0pt},
  input/.style={ellipse,draw=black,minimum width=24mm,minimum height=10mm,inner sep=0pt},
  flow/.style={draw=black,-{Stealth[length=1mm,width=0.7mm]},line width=0.8pt}
]
\path[use as bounding box] (0,-94) rectangle (76,7);
\node[anchor=west] at (0.5,0) {Common input};
\node[input] (common) at (50,0) {$\boldsymbol{10t+30}$};
\draw[flow] (common.south) -- (50,-8) -- (23,-8);
\draw[draw=black,line width=0.8pt] (23,-8) -- (23,-87);
\foreach \branch/\rowY/\position/\first/\second/\expression in {
  tl/-17/{Top left}/{\div 2}/{+5}/{5t+20},
  tr/-31/{Top right}/{-25}/{\div 5}/{2t+1},
  r/-45/{Right}/{\div 5}/{\times 3}/{6t+18},
  br/-59/{Bottom right}/{\div 10}/{\times 4}/{4t+12},
  bl/-73/{Bottom left}/{\times 2}/{-30}/{20t+30},
  l/-87/{Left}/{+10}/{\div 5}/{2t+8}
} {
  \node[anchor=west,align=left,text width=19mm] at (0.5,\rowY) {\position};
  \node[op] (first-\branch) at (31,\rowY) {$\first$};
  \node[op] (second-\branch) at (46.5,\rowY) {$\second$};
  \node[result] (result-\branch) at (65.5,\rowY) {$\expression$};
  \draw[flow] (23,\rowY) -- (first-\branch.west);
  \draw[flow] (first-\branch.east) -- (second-\branch.west);
  \draw[flow] (second-\branch.east) -- (result-\branch.west);
}
\end{tikzpicture}

